var customerId = input.get('customerId');
var subscriptionId = input.get('subscriptionId');
var accessToken = input.get('accessToken');

if (customerId) customerId = customerId.trim();
if (subscriptionId) subscriptionId = subscriptionId.trim();
if (accessToken) accessToken = accessToken.trim();

if (!customerId) {
    log.error('Customer ID is required');
    output.set('Error', 'Customer ID is required');
    tags.trigger('Error');
    return;
}

if (!accessToken) {
    log.error('Access Token is required');
    output.set('Error', 'Access Token is required');
    tags.trigger('Error');
    return;
}

var url = 'https://api.partnercenter.microsoft.com/v1/customers/' + customerId + '/subscriptions';
var isSingleFetch = subscriptionId && subscriptionId.length > 0;

if (isSingleFetch) {
    url = url + '/' + subscriptionId;
    log.info('Fetching single subscription: ' + subscriptionId);
} else {
    log.info('Fetching all subscriptions for customer: ' + customerId);
}

var response = http.get(url, {
    'Authorization': 'Bearer ' + accessToken,
    'Accept': '*/*'
});

if (response.statusCode >= 200 && response.statusCode < 300) {
    var data = json.parse(response.body);

    if (data.items) {
        // List response - multiple subscriptions
        output.set('TotalCount', data.totalCount || 0);
        output.set('Subscriptions', data.items);
        output.set('Subscription', null);
        log.info('Found ' + (data.totalCount || 0) + ' subscriptions');
    } else {
        // Single subscription response - flat object
        output.set('TotalCount', 1);
        output.set('Subscriptions', [data]);
        output.set('Subscription', data);  // Flat object!
        output.set('SubscriptionId', data.id);
        output.set('OfferName', data.offerName);
        output.set('FriendlyName', data.friendlyName);
        output.set('Status', data.status);
        output.set('BillingCycle', data.billingCycle);
        output.set('BillingType', data.billingType);
        log.info('Fetched: ' + data.friendlyName + ' (' + data.status + ')');
    }

    output.set('RawResponse', response.body);
    tags.trigger('Success');
} else {
    log.error('API call failed with status ' + response.statusCode);
    output.set('Error', 'HTTP ' + response.statusCode + ': ' + response.body);
    tags.trigger('Error');
}
